"""
The frontend page, as a Python string constant instead of a separate
static file -- served directly by Flask so it never depends on Vercel
correctly auto-detecting a public/ directory as static output.
"""
INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>MPPL Bills</title>\n<style>\n  :root {\n    --ink: #16211c;\n    --ink-soft: #4b5a52;\n    --paper: #f6f5f1;\n    --paper-raised: #ffffff;\n    --line: #d9d6cc;\n    --accent: #1f6b4c;\n    --accent-soft: #e4efe8;\n    --warn: #9a5b12;\n    --warn-soft: #fbf1e2;\n    --mono: \'SFMono-Regular\', Consolas, \'Liberation Mono\', Menlo, monospace;\n    --sans: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Inter, Helvetica, Arial, sans-serif;\n  }\n  * { box-sizing: border-box; }\n  body {\n    margin: 0;\n    font-family: var(--sans);\n    background: var(--paper);\n    color: var(--ink);\n    -webkit-font-smoothing: antialiased;\n  }\n  header {\n    padding: 28px 32px 20px;\n    border-bottom: 1px solid var(--line);\n  }\n  header h1 {\n    margin: 0;\n    font-size: 20px;\n    font-weight: 650;\n    letter-spacing: -0.01em;\n  }\n  header p {\n    margin: 4px 0 0;\n    color: var(--ink-soft);\n    font-size: 13.5px;\n  }\n  main {\n    max-width: 1080px;\n    margin: 0 auto;\n    padding: 28px 32px 64px;\n  }\n  section {\n    background: var(--paper-raised);\n    border: 1px solid var(--line);\n    border-radius: 10px;\n    padding: 20px 22px;\n    margin-bottom: 20px;\n  }\n  section h2 {\n    margin: 0 0 14px;\n    font-size: 13px;\n    font-weight: 650;\n    text-transform: none;\n    color: var(--ink-soft);\n  }\n  .dropzone {\n    border: 1.5px dashed var(--line);\n    border-radius: 8px;\n    padding: 28px;\n    text-align: center;\n    color: var(--ink-soft);\n    cursor: pointer;\n    transition: border-color 0.15s, background 0.15s;\n  }\n  .dropzone:hover, .dropzone.drag {\n    border-color: var(--accent);\n    background: var(--accent-soft);\n  }\n  .dropzone input { display: none; }\n  .upload-row {\n    display: flex;\n    gap: 10px;\n    margin-top: 14px;\n    align-items: center;\n    flex-wrap: wrap;\n  }\n  input[type=text], input[type=email], select {\n    font-family: var(--sans);\n    font-size: 13.5px;\n    padding: 8px 10px;\n    border: 1px solid var(--line);\n    border-radius: 6px;\n    background: #fff;\n    color: var(--ink);\n  }\n  button {\n    font-family: var(--sans);\n    font-size: 13.5px;\n    font-weight: 600;\n    padding: 8px 16px;\n    border-radius: 6px;\n    border: none;\n    background: var(--accent);\n    color: white;\n    cursor: pointer;\n  }\n  button:disabled { opacity: 0.5; cursor: default; }\n  button.ghost {\n    background: transparent;\n    color: var(--accent);\n    border: 1px solid var(--accent);\n    padding: 5px 10px;\n    font-size: 12.5px;\n  }\n  #upload-status { font-size: 13px; margin-top: 10px; min-height: 18px; }\n  #upload-status.ok { color: var(--accent); }\n  #upload-status.err { color: #a32323; }\n\n  .filters { display: flex; gap: 10px; flex-wrap: wrap; }\n\n  table { width: 100%; border-collapse: collapse; font-size: 13.5px; }\n  th {\n    text-align: left;\n    font-weight: 600;\n    color: var(--ink-soft);\n    font-size: 12px;\n    padding: 8px 10px;\n    border-bottom: 1px solid var(--line);\n  }\n  td { padding: 10px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }\n  tr:last-child td { border-bottom: none; }\n  td.num { font-family: var(--mono); font-variant-numeric: tabular-nums; text-align: right; }\n  .badge {\n    display: inline-block;\n    font-size: 11.5px;\n    font-weight: 600;\n    padding: 2px 8px;\n    border-radius: 100px;\n  }\n  .badge.paid { background: var(--accent-soft); color: var(--accent); }\n  .badge.unpaid, .badge.unknown { background: var(--warn-soft); color: var(--warn); }\n  .badge.pending_review { background: var(--warn-soft); color: var(--warn); }\n  .badge.confirmed { background: var(--accent-soft); color: var(--accent); }\n  a.filelink { color: var(--accent); text-decoration: none; font-size: 12.5px; }\n  a.filelink:hover { text-decoration: underline; }\n  #empty { color: var(--ink-soft); font-size: 13.5px; padding: 20px 0; text-align: center; }\n</style>\n</head>\n<body>\n\n<header>\n  <h1>MPPL Bills</h1>\n  <p>Upload a bill — it\'s read, filed, and made searchable automatically.</p>\n</header>\n\n<main>\n  <section>\n    <h2>Upload</h2>\n    <div class="dropzone" id="dropzone">\n      <div id="dropzone-label">Drop a bill here (JPG, PNG, or PDF) — or click to choose a file</div>\n      <input type="file" id="file-input" accept=".jpg,.jpeg,.png,.pdf">\n    </div>\n    <div class="upload-row">\n      <input type="email" id="uploaded-by" placeholder="your email">\n      <button id="upload-btn" disabled>Upload &amp; extract</button>\n    </div>\n    <div id="upload-status"></div>\n  </section>\n\n  <section>\n    <h2>Bills</h2>\n    <div class="filters" style="margin-bottom: 14px;">\n      <input type="text" id="f-vendor" placeholder="Search vendor…">\n      <select id="f-payment">\n        <option value="">Any payment status</option>\n        <option value="paid">Paid</option>\n        <option value="unpaid">Unpaid</option>\n        <option value="partially_paid">Partially paid</option>\n        <option value="unknown">Unknown</option>\n      </select>\n      <select id="f-review">\n        <option value="">Any review status</option>\n        <option value="pending_review">Pending review</option>\n        <option value="confirmed">Confirmed</option>\n      </select>\n      <button class="ghost" id="refresh-btn">Refresh</button>\n    </div>\n    <table id="bills-table">\n      <thead>\n        <tr>\n          <th>Vendor</th><th>Invoice</th><th>Date</th><th style="text-align:right">Amount</th>\n          <th>Payment</th><th>Review</th><th>File</th><th></th>\n        </tr>\n      </thead>\n      <tbody id="bills-body"></tbody>\n    </table>\n    <div id="empty" style="display:none">No bills match those filters yet.</div>\n  </section>\n</main>\n\n<script>\nconst dropzone = document.getElementById(\'dropzone\');\nconst fileInput = document.getElementById(\'file-input\');\nconst dzLabel = document.getElementById(\'dropzone-label\');\nconst uploadBtn = document.getElementById(\'upload-btn\');\nconst uploadedByInput = document.getElementById(\'uploaded-by\');\nconst statusEl = document.getElementById(\'upload-status\');\n\nlet selectedFile = null;\n\ndropzone.addEventListener(\'click\', () => fileInput.click());\ndropzone.addEventListener(\'dragover\', e => { e.preventDefault(); dropzone.classList.add(\'drag\'); });\ndropzone.addEventListener(\'dragleave\', () => dropzone.classList.remove(\'drag\'));\ndropzone.addEventListener(\'drop\', e => {\n  e.preventDefault();\n  dropzone.classList.remove(\'drag\');\n  if (e.dataTransfer.files.length) setFile(e.dataTransfer.files[0]);\n});\nfileInput.addEventListener(\'change\', () => { if (fileInput.files.length) setFile(fileInput.files[0]); });\n\nfunction setFile(f) {\n  selectedFile = f;\n  dzLabel.textContent = `Selected: ${f.name}`;\n  uploadBtn.disabled = false;\n}\n\nuploadBtn.addEventListener(\'click\', async () => {\n  if (!selectedFile) return;\n  const uploadedBy = uploadedByInput.value.trim() || \'unknown\';\n\n  uploadBtn.disabled = true;\n  statusEl.className = \'\';\n  statusEl.textContent = \'Reading and filing the bill — this takes a few seconds…\';\n\n  const form = new FormData();\n  form.append(\'file\', selectedFile);\n  form.append(\'uploaded_by\', uploadedBy);\n\n  try {\n    const res = await fetch(\'/api/upload\', { method: \'POST\', body: form });\n    const data = await res.json();\n    if (!res.ok) throw new Error(data.error || \'Upload failed\');\n\n    statusEl.className = \'ok\';\n    statusEl.textContent = `Saved — ${data.extracted.vendor_name}, ₹${data.extracted.amount ?? \'?\'}. Marked pending review.`;\n    selectedFile = null;\n    fileInput.value = \'\';\n    dzLabel.textContent = \'Drop a bill here (JPG, PNG, or PDF) — or click to choose a file\';\n    loadBills();\n  } catch (err) {\n    statusEl.className = \'err\';\n    statusEl.textContent = err.message;\n  } finally {\n    uploadBtn.disabled = false;\n  }\n});\n\nconst body = document.getElementById(\'bills-body\');\nconst emptyEl = document.getElementById(\'empty\');\n\nfunction badge(text, cls) {\n  return `<span class="badge ${cls}">${text.replace(\'_\', \' \')}</span>`;\n}\n\nasync function loadBills() {\n  const params = new URLSearchParams();\n  const vendor = document.getElementById(\'f-vendor\').value.trim();\n  const payment = document.getElementById(\'f-payment\').value;\n  const review = document.getElementById(\'f-review\').value;\n  if (vendor) params.set(\'vendor\', vendor);\n  if (payment) params.set(\'payment_status\', payment);\n  if (review) params.set(\'review_status\', review);\n\n  const res = await fetch(\'/api/bills?\' + params.toString());\n  const rows = await res.json();\n\n  body.innerHTML = \'\';\n  emptyEl.style.display = rows.length ? \'none\' : \'block\';\n\n  for (const r of rows) {\n    const tr = document.createElement(\'tr\');\n    const amount = r.amount != null ? Number(r.amount).toLocaleString(\'en-IN\', { minimumFractionDigits: 2 }) : \'—\';\n    tr.innerHTML = `\n      <td>${r.vendor_name || \'\'}</td>\n      <td>${r.invoice_no || \'—\'}</td>\n      <td>${r.invoice_date || \'—\'}</td>\n      <td class="num">${amount}</td>\n      <td>${badge(r.payment_status || \'unknown\', r.payment_status || \'unknown\')}</td>\n      <td>${badge(r.review_status || \'pending_review\', r.review_status || \'pending_review\')}</td>\n      <td>${r.drive_link ? `<a class="filelink" href="${r.drive_link}" target="_blank">Open</a>` : \'—\'}</td>\n      <td>${r.review_status === \'pending_review\' ? `<button class="ghost" data-id="${r.id}">Confirm</button>` : \'\'}</td>\n    `;\n    body.appendChild(tr);\n  }\n\n  body.querySelectorAll(\'button[data-id]\').forEach(btn => {\n    btn.addEventListener(\'click\', async () => {\n      const id = btn.getAttribute(\'data-id\');\n      const confirmedBy = uploadedByInput.value.trim() || \'unknown\';\n      await fetch(\'/api/confirm\', {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ id: Number(id), confirmed_by: confirmedBy }),\n      });\n      loadBills();\n    });\n  });\n}\n\ndocument.getElementById(\'refresh-btn\').addEventListener(\'click\', loadBills);\ndocument.getElementById(\'f-vendor\').addEventListener(\'keydown\', e => { if (e.key === \'Enter\') loadBills(); });\ndocument.getElementById(\'f-payment\').addEventListener(\'change\', loadBills);\ndocument.getElementById(\'f-review\').addEventListener(\'change\', loadBills);\n\nloadBills();\n</script>\n</body>\n</html>\n'